#!/usr/bin/env bash
# Regenerate dev/index.html (LOCAL ONLY, never uploaded to Qollab) from the root index.html.
# Source of truth for the markup: ../index.html (body content only). dev/index.html is generated:
# do not edit it by hand. It adds what Qollab provides itself: <html>/<head>, main.css, the import
# map (three, three/addons, and 'quantum.api' -> ui/mock-api.js) and the main.js module.
#
# Serve from the repo root:  python3 -m http.server 8123   ->  http://localhost:8123/dev/index.html
# Test switches: ?mock=ionq  ?mock=aria  ?mock=hang&timeout_ms=3000   (see ui/mock-api.js)
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
mkdir -p "$ROOT/dev"
OUT="$ROOT/dev/index.html"
{
cat <<'HEAD'
<!doctype html>
<!-- GENERATED by tools/make_dev_html.sh from ../index.html. Local development only. -->
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Entangle the Andes (dev)</title>
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Ccircle cx='16' cy='16' r='11' fill='%2335e0d0'/%3E%3Ccircle cx='16' cy='16' r='6' fill='%238a7cff'/%3E%3C/svg%3E" />
  <link rel="stylesheet" href="../main.css" />
  <script type="importmap">
    {
      "imports": {
        "three": "https://cdn.jsdelivr.net/npm/three@0.186.1/build/three.module.js",
        "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.186.1/examples/jsm/",
        "quantum.api": "../ui/mock-api.js"
      }
    }
  </script>
  <script>
    // Qollab creates the global `backend`. Locally there is none: ?mock=ionq|aria fakes an IonQ one.
    (function () {
      var m = new URLSearchParams(location.search).get("mock");
      if (m === "ionq" || m === "aria") window.backend = { name: "ionq_simulator" };
    })();
  </script>
</head>
<body>
HEAD
cat "$ROOT/index.html"
cat <<'TAIL'

  <script type="module" src="../main.js"></script>
</body>
</html>
TAIL
} > "$OUT"
echo "Wrote $OUT"
